def run(mode, rvas, targets, flo, fhi):
    canon = ROOT / "scripts" / "canonical" / "videocfg_windowed.bin"
    if canon.exists(): shutil.copy2(str(canon), str(ORIG / "videocfg.bin"))
    env = dict(os.environ); env["MASHED_RE_DEV"] = "1"
    env["MASHED_HOOK_ONLY"] = (",".join("0x%08x" % r for r in rvas) if mode == "on" else "__none__")
    NPG, DET = 0x00000200, 0x00000008
    dev = frida.get_local_device()
    proc = sess = None
    for _ in range(5):
        print(f"  [{mode}] EXE={EXE}", flush=True)
        proc = subprocess.Popen([str(EXE)], cwd=str(ORIG), env=env,
            stdin=subprocess.DEVNULL, stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL,
            creationflags=NPG | DET)
        time.sleep(0.2)
        print(f"  [{mode}] SPAWNED_PID={proc.pid}", flush=True)
        try: sess = dev.attach(proc.pid); break
        except Exception:
            try: proc.kill()
            except Exception: pass
            time.sleep(1.0)
    if sess is None: print(f"  [{mode}] attach failed"); return {}, {}
    scr = sess.create_script(CAP)
    scr.on("message", lambda m, d: print("  agent:", m.get("description")) if m["type"] == "error" else None)
    scr.load(); E = scr.exports_sync; E.init()
    samples, jmp = {}, {}

    def wait(pred, t, what):
        end = time.time()+t
        while time.time() < end:
            if pred(): return True
            time.sleep(0.1)
        return False
    def press(c, ms=180): E.press(c, ms); time.sleep(ms/1000.0+0.3)
    def confirm_to(tg, tries=6):
        for _ in range(tries):
            if E.depth() >= tg: return True
            press(4)
            if wait(lambda: E.depth() >= tg, 2.0, f"d{tg}"): return True
        return E.depth() >= tg
    try:
        if not wait(lambda: E.phase() == 3 and E.depth() >= 1, 30, "title"):
            print(f"  [{mode}] no title"); proc.kill(); return {}, {}
        time.sleep(1.0)
        E.setupcap(targets, mode, flo, fhi)          # arm BEFORE race so frame clock catches start
        confirm_to(2); time.sleep(0.4); press(4); time.sleep(0.8)
        confirm_to(3); E.setsel(1); time.sleep(0.3)
        confirm_to(4, 4); confirm_to(5, 4)
        press(4); time.sleep(1.5)
        for _ in range(5):
            if E.phase() != 3: break
            press(4); time.sleep(1.5)
        if E.phase() == 3: print(f"  [{mode}] not in race"); proc.kill(); return {}, {}
        print(f"  [{mode}] in race; waiting for frame window [{flo},{fhi}] ...")
        end = time.time() + 25
        while time.time() < end and E.frame() <= fhi:
            time.sleep(0.05)
        try: E.stopcap()                          # bound hot-path exposure once window closes
        except Exception: pass
        print(f"  [{mode}] frame={E.frame()}")
        samples = E.samples()
        if mode == "on": OBS.update(E.obsar() or {})   # bvh copy
        if mode == "on":
            for r in rvas:
                try: jmp[r] = E.jmpbyte(r)
                except Exception: jmp[r] = -1
    finally:
        try: proc.kill()
        except Exception: pass
    return samples, jmp

OBS = {}   # bvh copy: ON-observed callee arg counts
import re as _re   # bvh copy
MAPF = ROOT / "mashedmod" / "build" / "mashed_re_dev.map"
def _load_map():
    syms = []
    pat = _re.compile(r"^\s*0001:[0-9a-fA-F]{8}\s+(\S+)\s+([0-9a-fA-F]{8})\s")
    for line in MAPF.read_text(encoding="utf-8", errors="ignore").splitlines():
        m = pat.match(line)
        if m: syms.append((int(m.group(2), 16) - 0x10000000, m.group(1)))
    syms = sorted(set(syms))
    return syms
SYMS = _load_map(); SYM_ADDR = [a for a, _ in SYMS]
def _own_extra():
    d = {}
    for part in os.environ.get("C4_OWN_SYMS", "").split(";"):
        if ":" in part:
            r_, names = part.split(":", 1)
            d[int(r_, 16)] = {x.strip() for x in names.split(",") if x.strip()}
    return d
OWN_EXTRA = _own_extra()   # v8
def own_ranges(rva):
    tag = "fun_%08x" % rva; out = []; extra = OWN_EXTRA.get(rva, set())
    for i, (a, n) in enumerate(SYMS):
        if tag in n.lower() or n in extra:
            end = SYMS[i + 1][0] if i + 1 < len(SYMS) else a + 0x1000
            out.append([a, end])
    return out
SRC = ROOT / "mashedmod" / "src" / "mashed_re"
def _all_decls():
    """{rva: {param counts}} over every `__cdecl/__stdcall ... FUN_<rva>[_impl](...)` declaration in the tree."""
    pat = _re.compile(r"(?:__cdecl|__stdcall)[^;{(]*?\bFUN_([0-9a-fA-F]{8})(?:_impl)?\s*\(([^)]*)\)")
    d = {}
    for f in SRC.rglob("*.cpp"):
        for r_, a in pat.findall(f.read_text(encoding="utf-8", errors="ignore")):
            a = a.strip(); d.setdefault(int(r_, 16), set()).add(0 if a in ("", "void") else a.count(",") + 1)
    return d
DECLS = _all_decls()
def src_arity(rva):
    """Param count of the port's `__cdecl ... FUN_<rva>(...)` declaration; -1 if absent or the
    declarations disagree. Same value on the OFF and ON side (it only picks which entry args anchor)."""
    s = DECLS.get(rva, set())
    return next(iter(s)) if len(s) == 1 else -1
def ret_kind(rva):
    """'void' | '16' | 'full' from the port's extern "C" declaration (one consistent type, else 'full')."""
    pat = _re.compile(r'extern\s+"C"\s+([\w\s\*]+?)\s+__cdecl\s+FUN_%08x\s*\(' % rva)
    kinds = set()
    for f in SRC.rglob("*.cpp"):
        t = f.read_text(encoding="utf-8", errors="ignore")
        if ("FUN_%08x" % rva) not in t: continue
        for ty in pat.findall(t):
            ty = " ".join(ty.split())
            kinds.add("void" if ty == "void" else "16" if ty in ("undefined2", "ushort", "short", "unsigned short", "uint16_t") else "full")
    return kinds.pop() if len(kinds) == 1 else "full"
def callee_arity_maps():
    """Declared arity of every ported callee, keyed by image RVA and by .asi wrapper offset (`_FUN_<rva>`)."""
    img = {r_: next(iter(s)) for r_, s in DECLS.items() if len(s) == 1 and next(iter(s)) <= 16}
    asi = {}
    for a, n in SYMS:
        m = _re.fullmatch(r"_FUN_([0-9a-fA-F]{8})", n)
        if m and int(m.group(1), 16) in img: asi[a] = img[int(m.group(1), 16)]
    return img, asi
TRANSP_TAGS = ("shadowab@@", "shadowtrack@@", "security_check_cookie")
TRANSP_EXTRA = tuple(x.strip().lower() for x in os.environ.get("C4_TRANSP_SYMS", "").split(",") if x.strip())   # v8
def transparent_ranges():
    """[lo, hi, skip]: skip = leading template args of ShadowAB::Run (Counter&, impl) = 2,
    RunTracked (+ stackwin) = 3, RunRegion (+ region, bytes) = 4 (ShadowAB.h:223/280,
    ShadowTrack.h:647); -1 for everything else (not recorded)."""
    out = []
    for i, (a, n) in enumerate(SYMS):
        if any(x in n.lower() for x in TRANSP_TAGS + TRANSP_EXTRA):
            end = SYMS[i + 1][0] if i + 1 < len(SYMS) else a + 0x100
            skip = (3 if n.startswith("??$RunTracked@") else 4 if n.startswith("??$RunRegion@")
                    else 2 if n.startswith("??$Run@") else -1)
            out.append([a, end, skip])
    return out
def _sym(off):
    i = bisect.bisect_right(SYM_ADDR, off) - 1
    if i < 0: return "a:?%x" % off
    n = SYMS[i][1]; m = _re.search(r"FUN_([0-9a-fA-F]{8})", n)
    if m: return "c%x" % int(m.group(1), 16)
    if n in ("__chkstk", "__alloca_probe") and off == SYMS[i][0]: return "c4a3440"   # same role: 0x004a3440
    return "a:" + n + ("+%x" % (off - SYMS[i][0]) if off != SYMS[i][0] else "")
_ATOK = _re.compile(r"(?<=[\[,= ])a([0-9a-f]+)(?=[\],\s]|$)")
def symb(samples):
    out = {}
    for k, d in (samples or {}).items():
        nd = {}
        for sig, c in (d or {}).items():
            s2 = _ATOK.sub(lambda m: _sym(int(m.group(1), 16)), sig)
            nd[s2] = nd.get(s2, 0) + c
        out[k] = nd
    return out

def main():
    av = sys.argv
    def opt(f, d): return av[av.index(f)+1] if f in av else d
    rvas = [int(x, 16) for x in opt("--rvas", "").split(",") if x.strip()]
    if not rvas: print("need --rvas"); return 1
    flo = int(opt("--lo", "300")); fhi = int(opt("--hi", "1200"))   # A4-call (frame) window
    LOG.mkdir(parents=True, exist_ok=True)
    hooks = ROOT / "hooks.csv"
    if not hooks.exists(): hooks = ROOT.parent.parent / "hooks.csv"
    fs = []
    for line in hooks.read_text(encoding="utf-8", errors="ignore").splitlines():
        if not line or line[0] == "#" or line.startswith("rva,"): continue
        c = line.split(",", 1)[0].strip()
        try: fs.append(int(c, 16))
        except ValueError: pass
    fs = sorted(set(fs))
    def boundary(r):
        i = bisect.bisect_right(fs, r); return fs[i] if i < len(fs) else (r + 0x1800)
    TR = transparent_ranges()
    print("  bvh tool v8 scenario=" + os.environ.get("C4_SCENARIO", "quickbattle"))
    IMG_AR, ASI_AR = callee_arity_maps()
    REGS = {int(x, 16) for x in os.environ.get("C4_REGS", "").split(",") if x.strip()}   # v8
    targets = [[r, boundary(r), own_ranges(r), TR, src_arity(r), IMG_AR, ASI_AR, ret_kind(r), 1 if r in REGS else 0] for r in rvas]   # bvh copy: + .asi own / transparent ranges, arities, return kind
    print(f"  return kind={[t[7] for t in targets]}")
    print(f"  regs leg={[t[8] for t in targets]}  own extra={OWN_EXTRA}  transp extra={TRANSP_EXTRA}")
    print(f"  arity={[t[4] for t in targets]}")
    print(f"  own asi ranges={[[hex(a), hex(b)] for t in targets for a, b in t[2]]}")
    print(f"  targets={[hex(r) for r in rvas]}  frame-window=[{flo},{fhi}]")

    print("=== ON race ===");  on_s, on_jmp = run("on", rvas, targets, flo, fhi)   # bvh copy: ON first
    for tok, n in OBS.items():
        c = tok if tok.startswith("c") else _sym(int(tok[1:], 16))
        if c.startswith("c") and n <= 16: IMG_AR.setdefault(int(c[1:], 16), n)
    print(f"  ON-observed callee arities: {len(OBS)}")
    targets = [t[:5] + [IMG_AR] + t[6:] for t in targets]   # keeps ASI_AR and the return kind (v4 dropped it on OFF)
    print("\n=== OFF race ==="); off_s, _ = run("off", rvas, targets, flo, fhi)

    off_s = symb(off_s); on_s = symb(on_s)   # bvh copy
    (LOG / "c4_racediff_samples.json").write_text(json.dumps({"off": off_s, "on": on_s}, indent=1), encoding="utf-8")
    print("\n=== VERDICT (in-race, frame-synced, indirect captured) ===")
    out = {}; n_clean = 0
    for r in rvas:
        offset = set((off_s.get(r, off_s.get(str(r), {})) or {}).keys())
        onset = set((on_s.get(r, on_s.get(str(r), {})) or {}).keys())
        installed = (on_jmp.get(r, on_jmp.get(str(r), -1)) == 0xe9)
        why = []
        if not offset: why.append("orig-not-observed")
        if not onset: why.append("modded-not-observed")
        if offset and onset and offset != onset: why.append("BEHAVIOR-DIFF")
        if not installed: why.append("no-JMP")
        clean = bool(offset) and bool(onset) and offset == onset and installed
        verdict = "C4-CLEAN" if clean else "HOLD"
        if clean: n_clean += 1
        def trunc(s): return sorted({(x[:120] + '..' if len(x) > 122 else x) for x in s})
        out[r] = {"rva": "%#010x" % r, "verdict": verdict, "why": why, "installed": installed,
                  "off_n": len(offset), "on_n": len(onset), "off": trunc(offset)[:4], "on": trunc(onset)[:4]}
        print(f"  {r:#010x} -> {verdict}  {','.join(why)}  (off {len(offset)} sigs, on {len(onset)} sigs)")
        if verdict != "C4-CLEAN":
            print(f"        off={trunc(offset)[:3]}"); print(f"        on ={trunc(onset)[:3]}")
    (LOG / "c4_racediff_result.json").write_text(json.dumps(out, indent=2), encoding="utf-8")
    print(f"\n  {n_clean}/{len(rvas)} C4-CLEAN  ->  log/c4_racediff_result.json")
    return 0

# ---- v6: census scenario driver -------------------------------------------------------------------
import threading
LAUNCH = ROOT / "re" / "frida" / "scenario_launch.py"
def run_census(mode, rvas, targets, flo, fhi):
    env = dict(os.environ); env["MASHED_NO_SELFTEST"] = "1"; env.pop("MASHED_SHADOW_AB", None)
    env.setdefault("MASHED_MUTE", "1")
    cmd = [sys.executable, str(LAUNCH), "--track", "0", "--mode", "10", "--cars", "4", "--hold",
           os.environ.get("C4_HOLD", "60")]
    # v7 (D4-WSB-BVH-FU): OFF passes --hooks __none__ (asi loaded, MASHED_HOOK_ONLY matches nothing), as the
    # Quick Battle OFF arm does. With no --hooks the launcher sets MASHED_RE_NO_AUTO_HOOK=1 and dinput8_shim.cpp
    # (LoadDevAsi) then never loads the .asi, so asiloaded() stayed false until the game exited (v6, 4/4).
    cmd += ["--hooks", ",".join("0x%08x" % r for r in rvas) if mode == "on" else "__none__"]
    lp = subprocess.Popen(cmd, cwd=str(ROOT), env=env, stdout=subprocess.PIPE, stderr=subprocess.STDOUT,
                          text=True, encoding="utf-8", errors="replace")
    box = {"pid": 0, "lines": []}
    got = threading.Event()
    def drain():
        for ln in lp.stdout:
            box["lines"].append(ln)
            m = _re.search(r"scenario_launch\s+pid=(\d+)", ln)
            if m and not box["pid"]: box["pid"] = int(m.group(1)); got.set()
    th = threading.Thread(target=drain, daemon=True); th.start()
    samples, jmp = {}, {}
    pid = 0
    try:
        if not got.wait(60): print(f"  [{mode}] launcher printed no pid"); return {}, {}
        pid = box["pid"]; print(f"  [{mode}] SPAWNED_PID={pid}", flush=True)
        dev = frida.get_local_device(); sess = None
        for _ in range(100):
            try: sess = dev.attach(pid); break
            except Exception: time.sleep(0.1)
        if sess is None: print(f"  [{mode}] attach failed"); return {}, {}
        scr = sess.create_script(CAP)
        scr.on("message", lambda m, d: print("  agent:", m.get("description")) if m["type"] == "error" else None)
        scr.load(); E = scr.exports_sync; E.init()
        end = time.time() + 90
        while time.time() < end and lp.poll() is None:   # v7: stop when the launcher (and game) is gone
            ok = E.asiloaded()
            if ok and mode == "on": ok = all(E.jmpbyte(r) == 0xe9 for r in rvas)
            if ok: break
            time.sleep(0.05)
        if lp.poll() is not None: print(f"  [{mode}] launcher exited before arming"); return {}, {}
        print(f"  [{mode}] armed: asi={E.asiloaded()} jmp={[E.jmpbyte(r) for r in rvas]}", flush=True)
        if not E.asiloaded(): print(f"  [{mode}] asi never loaded: no capture"); return {}, {}
        E.setupcap(targets, mode, flo, fhi)
        end = time.time() + 150
        while time.time() < end and E.frame() <= fhi and lp.poll() is None:
            time.sleep(0.05)
        try: E.stopcap()
        except Exception: pass
        print(f"  [{mode}] frame={E.frame()}", flush=True)
        samples = E.samples()
        if mode == "on":
            OBS.update(E.obsar() or {})
            for r in rvas:
                try: jmp[r] = E.jmpbyte(r)
                except Exception: jmp[r] = -1
        try: sess.detach()
        except Exception: pass
    finally:
        if pid: subprocess.run(["taskkill", "/PID", str(pid), "/F"], capture_output=True)
        try: lp.wait(30)
        except Exception: lp.kill()
        (LOG / f"launcher_{mode}.txt").write_text("".join(box["lines"]), encoding="utf-8")
    return samples, jmp
if os.environ.get("C4_SCENARIO") == "census":
    run = run_census

if __name__ == "__main__":
    sys.exit(main())
